import{_ as l,l as i,o as e,c as s,v as o,p as n,x as t,d,i as c,S as m}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"布隆过滤器","description":"","frontmatter":{"title":"布隆过滤器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bloom-filter.md","filePath":"cs/bloom-filter.md","lastUpdated":1789023840000}'),p={name:"cs/bloom-filter.md"};function h(E,a,A,_,B,f){const r=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="布隆过滤器" tabindex="-1">布隆过滤器 <a class="header-anchor" href="#布隆过滤器" aria-label="Permalink to &quot;布隆过滤器&quot;">​</a></h1><div class="epigraph"><p>只问「可能在集合里吗」，允许把真正在的说成在、把不在的偶尔说成在；换来的是远小于存全体键的那一块位图。</p><footer>—— 据 Bloom, Space/Time Trade-offs in Hash Coding with Allowable Errors, CACM 1970 整理</footer></div><p><a href="/cs/robin-cuckoo">上一课</a>仍是精确字典：查到就是在，碰不到就是不在。<a href="/cs/hash-function">散列函数</a>给出 \\(h(k)\\)。本课不重讲探测序列。缺口是近似集：Bloom 用 \\(m\\) 位数组和 \\(k\\) 个散列，插入置位，查询若有一位为 0 则<strong>一定不在</strong>，全为 1 则<strong>可能在</strong>（假阳性）。跳表下一课回到精确有序结构；本课不保序、不存键。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>缓存、路由、数据库里经常先问「这个键有没有可能命中后面那份昂贵结构」。存完整散列集会太大。缺口不是再开一张布谷表，而是<strong>允许单侧错误</strong>：假阳性可接受，假阴性不可（标准 Bloom 无删除则不会假阴）。空间约 \\(m\\) 比特，与 \\(n\\) 和目标误差 \\(\\varepsilon\\) 有关，远小于存键。</p><p>删除：清位会误伤其他键。标准结构不支持删；计数 Bloom 是附录。</p><p><span class="marginnote">Bloom 1970 原文就是「允许错误的散列编码」。\\(k\\) 个独立均匀散列是分析假设；实践用两个散列派生多个下标。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>insert(x)</code>：对 \\(i=1..k\\) 置 <code>B[h_i(x)]=1</code>。<code>query(x)</code>：若某 <code>h_i(x)</code> 为 0 则否；否则报「可能」。假阳性率约 \\((1-e^{-kn/m})^k\\)，给定 \\(m,n\\) 可挑 \\(k\\) 使误差近最小（约 \\(k=(m/n)\\ln 2\\)）。本课不把求导写进主干，只钉误差随 \\(m/n\\) 与 \\(k\\) 降。</p>',9)),(e(),n(m,null,{default:t(()=>[c(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E9%94%AE%20x%22%5D%20--%3E%20H%5B%22k%20%E4%B8%AA%E4%B8%8B%E6%A0%87%22%5D%0A%20%20H%20--%3E%20SET%5B%22%E6%8F%92%E5%85%A5%EF%BC%9A%E9%82%A3%E4%BA%9B%E4%BD%8D%E7%BD%AE%E7%BD%AE%201%22%5D%0A%20%20H%20--%3E%20Q%5B%22%E6%9F%A5%E8%AF%A2%EF%BC%9A%E6%9C%89%200%20%E5%88%99%E4%B8%80%E5%AE%9A%E4%B8%8D%E5%9C%A8%22%5D%0A%20%20Q%20--%3E%20FP%5B%22%E5%85%A8%201%EF%BC%9A%E5%8F%AF%E8%83%BD%E5%81%87%E9%98%B3%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>与精确表串联：布隆说不在则跳过；说可能再查真字典。假阳只浪费一次精确查找。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>不存键，故不能迭代集合、不能返回卫星数据。这与字典合同不同，跳课的人若当 hashset 用会丢数据。局部性：一次查询碰 \\(k\\) 个可能分散的位，cache 行为不如线性探测；\\(m\\) 若适合放进 SRAM 则仍快。</p><p>再散列或扩容位图要重建，不能像动态数组那样只复制旧位——散列下标依赖 \\(m\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 cuckoo filter 的指纹、不把密码学哈希当必须。也不进入大模型词表或量化栏的「权重量化」——那是另一栏。安全栏的哈希抗碰撞与这里的均匀位图不是同一需求。</p><p>后课默认：只需过滤的否定查询用布隆。要精确有序字典且不想旋转，下一课跳表用随机层高。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>布隆：位图 + 多散列；无假阴（无删时），有假阳。</li><li>不存键，不是字典；误差由 \\(m,n,k\\) 管。</li><li>精确有序的期望对数结构是下一课跳表。</li><li>出处：Bloom, <em>CACM</em>, 1970。</li></ul>',9))])}const b=l(p,[["render",h]]);export{k as __pageData,b as default};
